CREATE OR REPLACE FUNCTION public.sellerpilot_service_prepare_gateway_credential_refresh(p_token_hash text, p_job_id uuid, p_claim_token uuid, p_secret_payload jsonb, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_recovery_only boolean DEFAULT false, p_oauth_complete boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_session sellerpilot_private.ebay_fresh_oauth_sessions%rowtype;
begin
  select * into v_session from sellerpilot_private.ebay_fresh_oauth_sessions where job_id=p_job_id;
  if found and not coalesce(p_recovery_only,false) then
    if p_oauth_complete is distinct from true
      or p_secret_payload is null
      or encode(extensions.digest(p_secret_payload->>'provider_account_subject','sha256'),'hex')
        is distinct from v_session.source_subject_sha256
      or (v_session.include_messages and not (
        string_to_array(coalesce(p_secret_payload->>'scopes',''),' ') @>
        array['https://api.ebay.com/oauth/api_scope/commerce.message'])) then
      raise exception 'fresh eBay same-seller authorization proof required' using errcode='42501';
    end if;
  end if;
  return public.sellerpilot_130520_prepare_before_ebay_fresh(
    p_token_hash,p_job_id,p_claim_token,p_secret_payload,p_expires_at,p_recovery_only,p_oauth_complete);
end $function$

sellerpilot_11820_prepare_refresh_unsafe.definition:
CREATE OR REPLACE FUNCTION public.sellerpilot_11820_prepare_refresh_unsafe(p_token_hash text, p_job_id uuid, p_claim_token uuid, p_secret_payload jsonb, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_recovery_only boolean DEFAULT false, p_oauth_complete boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_token_id uuid;
  v_job record;
  v_request_fingerprint text;
  v_refreshed_credential_id uuid;
  v_recovery_vault_id uuid;
begin
  if coalesce(p_token_hash, '') !~ '^[a-f0-9]{64}$'
     or p_claim_token is null then
    raise exception 'invalid worker token' using errcode = '42501';
  end if;

  select t.id into v_token_id
    from sellerpilot_private.ai_cli_worker_tokens t
   where t.token_hash = p_token_hash
     and t.status = 'active'
     and t.expires_at > now();
  if v_token_id is null then
    raise exception 'invalid worker token' using errcode = '42501';
  end if;

  select
    j.id,
    j.channel,
    j.operation,
    j.credential_id,
    j.prepared_credential_id,
    j.credential_refresh_fingerprint,
    j.credential_refresh_recovery_vault_id,
    j.credential_refresh_recovery_fingerprint,
    j.credential_refresh_in_flight
  into v_job
    from sellerpilot_private.channel_gateway_jobs j
   where j.id = p_job_id
     and j.status = 'running'
     and j.worker_token_id = v_token_id
     and j.claim_token = p_claim_token
     and j.lease_expires_at > now()
   for update;
  if not found then return null; end if;

  v_request_fingerprint := encode(extensions.digest(
    jsonb_build_object(
      'payload', p_secret_payload,
      'expires_at', p_expires_at,
      'recovery_only', p_recovery_only
    )::text,
    'sha256'
  ), 'hex');

  if p_secret_payload is null
     or jsonb_typeof(p_secret_payload) <> 'object'
     or octet_length(p_secret_payload::text) > 32000
     or v_job.channel not in ('shopee', 'lazada', 'ebay')
     or (p_oauth_complete and (p_recovery_only or v_job.operation <> 'oauth.exchange')) then
    return jsonb_build_object('status', 'invalid');
  end if;

  -- A Shopee main-account authorization returns a rotating token before the
  -- first shop-scoped token exists. It is not yet a usable channel credential,
  -- but losing it on a worker crash would consume the one-time OAuth grant.
  -- Preserve that intermediate snapshot in Vault under the exact live claim;
  -- it is never activated or handed to queued marketplace jobs.
  if p_recovery_only then
    if v_job.channel <> 'shopee'
       or v_job.operation <> 'oauth.exchange'
       or coalesce(p_secret_payload->>'partner_id', '') !~ '^[0-9]+$'
       or length(coalesce(p_secret_payload->>'partner_key', '')) < 16
       or coalesce(p_secret_payload->>'main_account_id', '') !~ '^[0-9]+$'
       or length(coalesce(p_secret_payload->>'main_account_access_token', '')) < 8
       or length(coalesce(p_secret_payload->>'main_account_refresh_token', '')) < 8
       or p_expires_at is null
       or p_expires_at <= now() then
      return jsonb_build_object('status', 'invalid');
    end if;

    if v_job.credential_refresh_recovery_vault_id is not null
       and v_job.credential_refresh_recovery_fingerprint = v_request_fingerprint then
      return jsonb_build_object('status', 'recovery_preserved', 'reused', true);
    end if;
    if not v_job.credential_refresh_in_flight then
      return jsonb_build_object('status', 'conflict');
    end if;

    select vault.create_secret(
      p_secret_payload::text,
      format('sellerpilot_gateway_recovery_%s_%s_%s', v_job.channel, v_job.id, gen_random_uuid()),
      'SellerPilot claim-bound OAuth recovery snapshot. Never expose outside manual reconciliation.'
    ) into v_recovery_vault_id;

    if v_job.credential_refresh_recovery_vault_id is not null then
      delete from vault.secrets where id = v_job.credential_refresh_recovery_vault_id;
    end if;

    update sellerpilot_private.channel_gateway_jobs j
       set credential_refresh_recovery_vault_id = v_recovery_vault_id,
           credential_refresh_recovery_fingerprint = v_request_fingerprint,
           credential_refresh_recovery_staged_at = now(),
           credential_refresh_in_flight = false,
           credential_refresh_started_at = null,
           updated_at = now()
     where j.id = v_job.id;

    return jsonb_build_object('status', 'recovery_preserved', 'reused', false);
  end if;

  if v_job.prepared_credential_id is not null
     and v_job.credential_refresh_fingerprint = v_request_fingerprint then
    if p_oauth_complete then
      update sellerpilot_private.channel_gateway_jobs j
         set oauth_exchange_completed = true,
             updated_at = now()
       where j.id = v_job.id
         and j.operation = 'oauth.exchange'
         and j.credential_refresh_in_flight = false
         and j.credential_refresh_recovery_vault_id is null;
      if not found then return jsonb_build_object('status', 'conflict'); end if;
    end if;
    return jsonb_build_object(
      'status', 'prepared',
      'credential_id', v_job.prepared_credential_id,
      'reused', true,
      'oauth_complete', p_oauth_complete
    );
  end if;
  if not v_job.credential_refresh_in_flight then
    return jsonb_build_object('status', 'conflict');
  end if;

  if v_job.channel = 'shopee' and (
    coalesce(p_secret_payload->>'partner_id', '') !~ '^[0-9]+$'
    or length(coalesce(p_secret_payload->>'partner_key', '')) < 16
    or coalesce(p_secret_payload->>'shop_id', '') !~ '^[0-9]+$'
    or length(coalesce(p_secret_payload->>'access_token', '')) < 8
    or length(coalesce(p_secret_payload->>'refresh_token', '')) < 8
  ) then
    return jsonb_build_object('status', 'invalid');
  end if;

  if v_job.channel = 'lazada' and (
    length(coalesce(p_secret_payload->>'access_token', '')) < 8
    or length(coalesce(p_secret_payload->>'refresh_token', '')) < 8
    or p_expires_at is null
    or p_expires_at <= now()
  ) then
    return jsonb_build_object('status', 'invalid');
  end if;

  if v_job.channel = 'ebay' and (
    length(coalesce(p_secret_payload->>'access_token', '')) < 8
    or length(coalesce(p_secret_payload->>'refresh_token', '')) < 8
    or length(coalesce(p_secret_payload->>'client_id', '')) < 3
    or length(coalesce(p_secret_payload->>'client_secret', '')) < 3
    or p_expires_at is null
    or p_expires_at <= now()
  ) then
    return jsonb_build_object('status', 'invalid');
  end if;

  perform 1
    from sellerpilot_private.channel_credentials c
   where c.id = v_job.credential_id
     and c.channel = v_job.channel
     and c.status = 'active'
   for update;
  if not found then return jsonb_build_object('status', 'conflict'); end if;

  v_refreshed_credential_id := case v_job.channel
    when 'shopee' then public.sellerpilot_service_refresh_shopee(
      v_job.credential_id,
      p_secret_payload,
      p_expires_at
    )
    when 'lazada' then public.sellerpilot_service_refresh_lazada(
      v_job.credential_id,
      p_secret_payload,
      p_expires_at
    )
    when 'ebay' then public.sellerpilot_service_refresh_ebay(
      v_job.credential_id,
      p_secret_payload,
      p_expires_at
    )
  end;

  update sellerpilot_private.channel_gateway_jobs queued
     set credential_id = v_refreshed_credential_id,
         updated_at = now()
   where queued.credential_id = v_job.credential_id
     and queued.status = 'queued';

  if v_job.credential_refresh_recovery_vault_id is not null then
    delete from vault.secrets where id = v_job.credential_refresh_recovery_vault_id;
  end if;

  update sellerpilot_private.channel_gateway_jobs j
     set credential_id = v_refreshed_credential_id,
         prepared_credential_id = v_refreshed_credential_id,
         credential_refresh_fingerprint = v_request_fingerprint,
         credential_refresh_prepared_at = now(),
         credential_refresh_recovery_vault_id = null,
         credential_refresh_recovery_fingerprint = null,
         credential_refresh_recovery_staged_at = null,
         credential_refresh_in_flight = false,
         credential_refresh_started_at = null,
         oauth_exchange_completed = p_oauth_complete and v_job.operation = 'oauth.exchange',
         updated_at = now()
   where j.id = v_job.id;

  return jsonb_build_object(
    'status', 'prepared',
    'credential_id', v_refreshed_credential_id,
    'reused', false,
    'oauth_complete', p_oauth_complete and v_job.operation = 'oauth.exchange'
  );
end;
$function$

sellerpilot_service_refresh_shopee.definition:
CREATE OR REPLACE FUNCTION public.sellerpilot_service_refresh_shopee(p_credential_id uuid, p_secret_payload jsonb, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'sellerpilot_private', 'vault'
AS $function$
declare
  v_id uuid := gen_random_uuid();
  v_vault_id uuid;
  v_version integer;
  v_environment text;
  v_created_by uuid;
  v_existing_expires_at timestamptz;
  v_fingerprint text;
begin
  if jsonb_typeof(p_secret_payload) <> 'object'
     or (p_secret_payload->>'partner_id') !~ '^[0-9]+$'
     or length(coalesce(p_secret_payload->>'partner_key', '')) < 16
     or (p_secret_payload->>'shop_id') !~ '^[0-9]+$'
     or length(coalesce(p_secret_payload->>'access_token', '')) < 8
     or length(coalesce(p_secret_payload->>'refresh_token', '')) < 8
     or octet_length(p_secret_payload::text) > 32000 then
    raise exception 'invalid refreshed credential';
  end if;

  select c.environment, c.created_by, c.expires_at
    into v_environment, v_created_by, v_existing_expires_at
    from sellerpilot_private.channel_credentials c
   where c.id = p_credential_id and c.channel = 'shopee' and c.status = 'active'
   for update;
  if not found then raise exception 'active Shopee credential not found'; end if;

  perform pg_advisory_xact_lock(hashtext('sellerpilot:shopee:' || v_environment));
  select coalesce(max(c.version), 0) + 1 into v_version
    from sellerpilot_private.channel_credentials c
   where c.channel = 'shopee' and c.environment = v_environment;

  v_fingerprint := upper(substr(encode(extensions.digest(p_secret_payload::text, 'sha256'), 'hex'), 1, 12));
  select vault.create_secret(
    p_secret_payload::text,
    format('sellerpilot_shopee_%s_v%s_%s', v_environment, v_version, v_id),
    'SellerPilot refreshed Shopee OAuth credential. Never expose to browser or logs.'
  ) into v_vault_id;

  update sellerpilot_private.channel_credentials set status = 'revoked', grace_ends_at = now()
   where id = p_credential_id;
  insert into sellerpilot_private.channel_credentials (
    id, channel, environment, version, vault_secret_id, fingerprint, status,
    expires_at, rotation_interval_days, warning_days, last_rotated_at,
    last_checked_at, last_check_status, last_check_message, created_by
  )
  select v_id, 'shopee', v_environment, v_version, v_vault_id, v_fingerprint, 'active',
         coalesce(p_expires_at, v_existing_expires_at), c.rotation_interval_days,
         c.warning_days, now(), c.last_checked_at, c.last_check_status,
         c.last_check_message, v_created_by
    from sellerpilot_private.channel_credentials c where c.id = p_credential_id;

  update sellerpilot_private.channel_gateway_jobs
     set credential_id = v_id, updated_at = now()
   where credential_id = p_credential_id and status = 'queued' and attempt_id is null;

  insert into sellerpilot_private.credential_audit (
    credential_id, channel, environment, action, actor_user_id, safe_detail
  ) values (
    v_id, 'shopee', v_environment, 'token_refreshed', null,
    jsonb_build_object('version', v_version, 'fingerprint', v_fingerprint,
      'expires_at', coalesce(p_expires_at, v_existing_expires_at),
      'source', 'service_refresh', 'diagnostic_preserved', true)
  );
  return v_id;
end;
$function$

sellerpilot_54851_prepare_refresh_identi.definition:
CREATE OR REPLACE FUNCTION public.sellerpilot_54851_prepare_refresh_identity_unsafe(p_token_hash text, p_job_id uuid, p_claim_token uuid, p_secret_payload jsonb, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_recovery_only boolean DEFAULT false, p_oauth_complete boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_job_channel text;
  v_job_operation text;
  v_old_subject text;
  v_new_subject text;
  v_identity_version text;
  v_recovery_vault_id uuid;
  v_existing_recovery_vault_id uuid;
  v_existing_recovery_fingerprint text;
  v_refresh_in_flight boolean;
  v_request_fingerprint text;
begin
  perform pg_catalog.pg_advisory_xact_lock(193674993, 821065042);

  if coalesce(p_token_hash, '') !~ '^[a-f0-9]{64}$' or p_claim_token is null then
    raise exception 'invalid worker token' using errcode = '42501';
  end if;
  perform 1
    from sellerpilot_private.ai_cli_worker_tokens worker_token
   where worker_token.token_hash = p_token_hash
     and worker_token.status = 'active'
     and worker_token.expires_at > now();
  if not found then
    raise exception 'invalid worker token' using errcode = '42501';
  end if;

  select j.channel, j.operation,
         nullif(trim(old_secret.decrypted_secret::jsonb->>'provider_account_subject'), ''),
         j.credential_refresh_recovery_vault_id,
         j.credential_refresh_recovery_fingerprint,
         j.credential_refresh_in_flight
    into v_job_channel, v_job_operation, v_old_subject,
         v_existing_recovery_vault_id, v_existing_recovery_fingerprint,
         v_refresh_in_flight
    from sellerpilot_private.channel_gateway_jobs j
    join sellerpilot_private.channel_credentials c on c.id = j.credential_id
    join vault.decrypted_secrets old_secret on old_secret.id = c.vault_secret_id
    join sellerpilot_private.ai_cli_worker_tokens worker_token
      on worker_token.id = j.worker_token_id
   where j.id = p_job_id
     and j.claim_token = p_claim_token
     and j.status = 'running'
     and j.lease_expires_at > now()
     and worker_token.token_hash = p_token_hash
     and worker_token.status = 'active'
     and worker_token.expires_at > now()
   for update of j;

  if not found then return null; end if;

  -- eBay OAuth exchange and Lazada token refresh can return rotating grants
  -- before the immutable account proof is durably staged. Preserve a
  -- claim-bound snapshot in Vault first; it is never activated without the
  -- subsequent provider identity proof.
  if p_recovery_only and v_job_channel in ('ebay', 'lazada', 'shopee') then
    if (v_job_channel = 'ebay' and v_job_operation <> 'oauth.exchange')
       or p_secret_payload is null
       or jsonb_typeof(p_secret_payload) <> 'object'
       or octet_length(p_secret_payload::text) > 32000
       or p_secret_payload ? 'provider_account_subject'
       or p_secret_payload ? 'provider_account_identity_version'
       or (
         v_job_channel in ('ebay', 'lazada')
         and (
           length(coalesce(p_secret_payload->>'access_token', '')) < 8
           or length(coalesce(p_secret_payload->>'refresh_token', '')) < 8
         )
       )
       or (
         v_job_channel = 'ebay'
         and (
           length(coalesce(p_secret_payload->>'client_id', '')) < 3
           or length(coalesce(p_secret_payload->>'client_secret', '')) < 3
         )
       )
       or (
         v_job_channel = 'lazada'
         and (
           length(coalesce(p_secret_payload->>'app_key', '')) < 3
           or length(coalesce(p_secret_payload->>'app_secret', '')) < 3
         )
       )
       or (
         v_job_channel = 'shopee'
         and (
           coalesce(p_secret_payload->>'partner_id', '') !~ '^[0-9]+$'
           or length(coalesce(p_secret_payload->>'partner_key', '')) < 16
           or not (
             (
               coalesce(p_secret_payload->>'main_account_id', '') ~ '^[0-9]+$'
               and length(coalesce(p_secret_payload->>'main_account_access_token', '')) >= 8
               and length(coalesce(p_secret_payload->>'main_account_refresh_token', '')) >= 8
             )
             or (
               coalesce(
                 nullif(p_secret_payload->>'shop_id', ''),
                 nullif(p_secret_payload->>'merchant_id', '')
               ) ~ '^[0-9]+$'
               and length(coalesce(p_secret_payload->>'access_token', '')) >= 8
               and length(coalesce(p_secret_payload->>'refresh_token', '')) >= 8
             )
           )
         )
       )
       or (v_job_channel <> 'shopee' and p_expires_at is null)
       or (p_expires_at is not null and p_expires_at <= now())
       or p_oauth_complete then
      return jsonb_build_object('status', 'invalid');
    end if;

    v_request_fingerprint := encode(extensions.digest(
      jsonb_build_object(
        'payload', p_secret_payload,
        'expires_at', p_expires_at,
        'recovery_only', true
      )::text,
      'sha256'
    ), 'hex');
    if v_existing_recovery_vault_id is not null
       and v_existing_recovery_fingerprint = v_request_fingerprint then
      return jsonb_build_object('status', 'recovery_preserved', 'reused', true);
    end if;
    if not v_refresh_in_flight then
      return jsonb_build_object('status', 'conflict');
    end if;

    select vault.create_secret(
      p_secret_payload::text,
      format('sellerpilot_gateway_recovery_%s_%s_%s', v_job_channel, p_job_id, gen_random_uuid()),
      format(
        'SellerPilot claim-bound %s OAuth recovery snapshot. Never expose outside manual reconciliation.',
        v_job_channel
      )
    ) into v_recovery_vault_id;
    if v_existing_recovery_vault_id is not null then
      delete from vault.secrets where id = v_existing_recovery_vault_id;
    end if;
    update sellerpilot_private.channel_gateway_jobs j
       set credential_refresh_recovery_vault_id = v_recovery_vault_id,
           credential_refresh_recovery_fingerprint = v_request_fingerprint,
           credential_refresh_recovery_staged_at = now(),
           credential_refresh_in_flight = false,
           credential_refresh_started_at = null,
           updated_at = now()
     where j.id = p_job_id;
    return jsonb_build_object('status', 'recovery_preserved', 'reused', false);
  end if;

  if v_job_channel in ('shopee', 'lazada', 'ebay') then
    v_new_subject := nullif(trim(p_secret_payload->>'provider_account_subject'), '');
    v_identity_version := nullif(trim(p_secret_payload->>'provider_account_identity_version'), '');
    if v_identity_version <> 'v1'
       or v_new_subject is null
       or length(v_new_subject) > 2048
       or (v_job_channel = 'shopee' and v_new_subject !~ '^shopee:(main|shop):[0-9]+$')
       or (v_job_channel = 'lazada' and (
         length(v_new_subject) not between 51 and 522
         or v_new_subject !~ '^lazada:v1:[A-Za-z0-9_-]+$'
       ))
       or (v_job_channel = 'ebay' and (
         length(v_new_subject) not between 11 and 522
         or v_new_subject !~ '^ebay:eias:[^[:cntrl:]]+$'
       )) then
      return jsonb_build_object('status', 'invalid');
    end if;

    -- A regular refresh may attest a previously-unattested legacy credential,
    -- but once a provider subject exists it can never switch accounts. A new
    -- OAuth exchange is the only flow allowed to establish a different lineage.
    if v_job_operation <> 'oauth.exchange'
       and v_old_subject is not null
       and v_new_subject is distinct from v_old_subject then
      return jsonb_build_object('status', 'identity_mismatch');
    end if;
  end if;

  return public.sellerpilot_11820_prepare_refresh_unsafe(
    p_token_hash,
    p_job_id,
    p_claim_token,
    p_secret_payload,
    p_expires_at,
    p_recovery_only,
    p_oauth_complete
  );
end;
$function$

sellerpilot_130520_prepare_before_ebay_f.definition:
CREATE OR REPLACE FUNCTION public.sellerpilot_130520_prepare_before_ebay_fresh(p_token_hash text, p_job_id uuid, p_claim_token uuid, p_secret_payload jsonb, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_recovery_only boolean DEFAULT false, p_oauth_complete boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_preparation jsonb;
  v_prepared_credential_id uuid;
  v_lineage record;
  v_updated integer;
begin
  v_preparation := public.sellerpilot_54851_prepare_refresh_identity_unsafe(
    p_token_hash,
    p_job_id,
    p_claim_token,
    p_secret_payload,
    p_expires_at,
    p_recovery_only,
    p_oauth_complete
  );
  if coalesce(v_preparation->>'status', '') <> 'prepared' then
    return v_preparation;
  end if;

  begin
    v_prepared_credential_id := (v_preparation->>'credential_id')::uuid;
  exception when invalid_text_representation then
    raise exception 'prepared provider credential identity is invalid';
  end;

  perform 1
    from sellerpilot_private.channel_gateway_jobs job
    join sellerpilot_private.ai_cli_worker_tokens worker_token
      on worker_token.id = job.worker_token_id
   where job.id = p_job_id
     and job.claim_token = p_claim_token
     and job.status = 'running'
     and job.lease_expires_at > now()
     and job.credential_id = v_prepared_credential_id
     and job.prepared_credential_id = v_prepared_credential_id
     and job.credential_refresh_prepared_at is not null
     and worker_token.token_hash = p_token_hash
     and worker_token.status = 'active'
     and worker_token.expires_at > now();
  if not found then
    raise exception 'prepared provider credential claim is unavailable';
  end if;

  perform set_config(
    'sellerpilot.provider_account_credential_attestation',
    'live:' || p_job_id::text || ':' || p_claim_token::text,
    true
  );
  select lineage.* into v_lineage
    from sellerpilot_private.channel_credentials credential
    cross join lateral sellerpilot_private.credential_seller_account_lineage(
      credential.channel,
      credential.environment,
      credential.vault_secret_id
    ) lineage
   where credential.id = v_prepared_credential_id;
  if v_lineage.seller_account_key !~ '^[a-f0-9]{64}$'
     or v_lineage.seller_account_key_source <> 'provider_certified_v1'
     or v_lineage.seller_account_verified_at is null then
    raise exception 'provider credential identity attestation failed';
  end if;

  update sellerpilot_private.channel_credentials credential
     set seller_account_key = v_lineage.seller_account_key,
         seller_account_key_source = v_lineage.seller_account_key_source,
         seller_account_verified_at = v_lineage.seller_account_verified_at
   where credential.id = v_prepared_credential_id
     and credential.seller_account_key is null
     and credential.seller_account_key_source = 'legacy_unattested'
     and credential.seller_account_verified_at is null;
  get diagnostics v_updated = row_count;
  if v_updated = 0 then
    perform 1
      from sellerpilot_private.channel_credentials credential
     where credential.id = v_prepared_credential_id
       and credential.seller_account_key = v_lineage.seller_account_key
       and credential.seller_account_key_source = 'provider_certified_v1'
       and credential.seller_account_verified_at is not null;
    if found then
      perform set_config('sellerpilot.provider_account_credential_attestation', '', true);
      return v_preparation;
    end if;
  end if;
  if v_updated <> 1 then
    raise exception 'prepared provider credential is unavailable';
  end if;
  perform set_config('sellerpilot.provider_account_credential_attestation', '', true);
  return v_preparation;
end;
$function$
